  // ==================== PATIENT HEALTH SUMMARY ====================


  app.get("/api/patient/health-summary", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);

      const allRecords = await storage.getHealthRecords(userId);

      const diagnoses = allRecords.filter((r: any) => r.type === "diagnosis" || r.type === "condition");
      const medications = allRecords.filter((r: any) => r.type === "medication");
      const labs = allRecords.filter((r: any) => r.type === "lab");
      const immunizations = allRecords.filter((r: any) => r.type === "immunization");
      const allergies = allRecords.filter((r: any) => r.type === "allergy");
      const vitals = allRecords.filter((r: any) => r.type === "vital");

      const pendingLabOrders = await db
        .select()
        .from(labOrders)
        .where(and(
          eq(labOrders.patientId, userId),
          sql`${labOrders.status} IN ('submitted', 'collected', 'in_progress', 'pending', 'draft')`
        ))
        .orderBy(desc(labOrders.createdAt))
        .limit(10);

      const recentLabs = labs
        .sort((a: any, b: any) => new Date(b.date).getTime() - new Date(a.date).getTime())
        .slice(0, 5)
        .map((r: any) => ({
          id: r.id,
          title: r.title,
          date: r.date,
          summary: r.summary,
          provider: r.provider,
          hasAbnormal: (r.details as any)?.hasAbnormal || false,
        }));

      const activeMedications = medications
        .filter((m: any) => {
          const details = m.details as any;
          return !details?.endDate || new Date(details.endDate) > new Date();
        })
        .slice(0, 10)
        .map((m: any) => ({
          id: m.id,
          title: m.title,
          summary: m.summary,
          provider: m.provider,
          dosage: (m.details as any)?.dosage || (m.details as any)?.dose,
          frequency: (m.details as any)?.frequency,
          status: (m.details as any)?.status || "active",
        }));

      const activeDiagnoses = diagnoses
        .filter((d: any) => {
          const details = d.details as any;
          return !details?.resolvedDate;
        })
        .slice(0, 10)
        .map((d: any) => ({
          id: d.id,
          title: d.title,
          date: d.date,
          summary: d.summary,
          provider: d.provider,
          icdCode: (d.details as any)?.icdCode,
          severity: (d.details as any)?.severity,
          status: (d.details as any)?.status || "active",
        }));

      const pendingOrders = pendingLabOrders.map((o: any) => ({
        id: o.id,
        orderNumber: o.orderNumber,
        status: o.status,
        tests: o.tests,
        labProvider: o.labProvider,
        orderedAt: o.createdAt,
        priority: o.priority,
      }));

      const summary = {
        totalRecords: allRecords.length,
        diagnosesCount: diagnoses.length,
        activeDiagnosesCount: activeDiagnoses.length,
        medicationsCount: medications.length,
        activeMedicationsCount: activeMedications.length,
        labResultsCount: labs.length,
        immunizationsCount: immunizations.length,
        allergiesCount: allergies.length,
        vitalsCount: vitals.length,
        pendingOrdersCount: pendingOrders.length,
      };

      res.json({
        summary,
        activeDiagnoses,
        activeMedications,
        recentLabs,
        pendingOrders,
      });
    } catch (error) {
      console.error("Patient health summary error:", error);
      res.status(500).json({ error: "Failed to fetch health summary" });
    }
  });

