  // ==================== CONSOLIDATED LAB RESULTS ====================


  app.get("/api/lab-results/consolidated", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { sortBy, sortOrder, testType, status, startDate, endDate } = req.query as any;

      const labHealthRecords = await db
        .select()
        .from(healthRecords)
        .where(and(eq(healthRecords.userId, userId), eq(healthRecords.type, "lab")))
        .orderBy(desc(healthRecords.date));

      const labOrderRecords = await db
        .select()
        .from(labOrders)
        .where(eq(labOrders.patientId, userId))
        .orderBy(desc(labOrders.createdAt));

      const REFERENCE_RANGES: Record<string, { low: number; high: number; unit: string; criticalLow?: number; criticalHigh?: number }> = {
        "WBC": { low: 4.5, high: 11.0, unit: "x10^3/uL", criticalLow: 2.0, criticalHigh: 30.0 },
        "RBC": { low: 4.2, high: 5.9, unit: "x10^6/uL", criticalLow: 2.5, criticalHigh: 8.0 },
        "Hemoglobin": { low: 12.0, high: 17.5, unit: "g/dL", criticalLow: 7.0, criticalHigh: 20.0 },
        "Hematocrit": { low: 36.0, high: 50.0, unit: "%", criticalLow: 20.0, criticalHigh: 60.0 },
        "Platelets": { low: 150, high: 400, unit: "x10^3/uL", criticalLow: 50, criticalHigh: 1000 },
        "Glucose": { low: 70, high: 100, unit: "mg/dL", criticalLow: 40, criticalHigh: 500 },
        "BUN": { low: 7, high: 20, unit: "mg/dL", criticalHigh: 100 },
        "Creatinine": { low: 0.7, high: 1.3, unit: "mg/dL", criticalHigh: 10.0 },
        "Sodium": { low: 136, high: 145, unit: "mEq/L", criticalLow: 120, criticalHigh: 160 },
        "Potassium": { low: 3.5, high: 5.0, unit: "mEq/L", criticalLow: 2.5, criticalHigh: 6.5 },
        "Total Cholesterol": { low: 0, high: 200, unit: "mg/dL" },
        "HDL Cholesterol": { low: 40, high: 100, unit: "mg/dL" },
        "LDL Cholesterol (calc)": { low: 0, high: 130, unit: "mg/dL" },
        "Triglycerides": { low: 0, high: 150, unit: "mg/dL" },
        "TSH": { low: 0.4, high: 4.5, unit: "mIU/L", criticalLow: 0.01, criticalHigh: 100 },
        "AST": { low: 10, high: 40, unit: "U/L", criticalHigh: 1000 },
        "ALT": { low: 7, high: 56, unit: "U/L", criticalHigh: 1000 },
        "ALP": { low: 44, high: 147, unit: "U/L" },
        "Total Bilirubin": { low: 0.1, high: 1.2, unit: "mg/dL", criticalHigh: 15.0 },
        "Albumin": { low: 3.5, high: 5.5, unit: "g/dL", criticalLow: 1.5 },
        "Calcium": { low: 8.5, high: 10.5, unit: "mg/dL", criticalLow: 6.0, criticalHigh: 13.0 },
        "HbA1c": { low: 4.0, high: 5.6, unit: "%", criticalHigh: 14.0 },
        "eGFR": { low: 90, high: 120, unit: "mL/min/1.73m2" },
      };

      function flagComponent(component: any) {
        const name = component.name || component.testName || "";
        const valueNum = parseFloat(component.value || component.valueNumeric);
        const range = REFERENCE_RANGES[name];
        
        let flag: "normal" | "low" | "high" | "critical_low" | "critical_high" = "normal";
        let referenceRange = component.referenceRange || null;
        
        if (range && !isNaN(valueNum)) {
          if (range.criticalLow && valueNum <= range.criticalLow) flag = "critical_low";
          else if (range.criticalHigh && valueNum >= range.criticalHigh) flag = "critical_high";
          else if (valueNum < range.low) flag = "low";
          else if (valueNum > range.high) flag = "high";
          
          if (!referenceRange) {
            referenceRange = { low: range.low, high: range.high, text: `${range.low}-${range.high} ${range.unit}` };
          }
        }

        if (component.interpretation && component.interpretation !== "normal" && flag === "normal") {
          flag = component.interpretation === "low" ? "low" : "high";
        }
        
        return { ...component, flag, referenceRange, isAbnormal: flag !== "normal", isCritical: flag === "critical_low" || flag === "critical_high" };
      }

      let consolidatedResults: any[] = [];

      for (const record of labHealthRecords) {
        const details = record.details as any;
        let components: any[] = [];
        
        if (details?.components) {
          components = details.components.map(flagComponent);
        } else if (details?.value !== undefined) {
          components = [flagComponent({ name: record.title, value: String(details.value), units: details.units || details.unit })];
        }
        
        const hasAbnormal = components.some((c: any) => c.isAbnormal);
        const hasCritical = components.some((c: any) => c.isCritical);
        const abnormalCount = components.filter((c: any) => c.isAbnormal).length;

        const testCategory = details?.category || details?.testCategory || categorizeLabTest(record.title);
        
        consolidatedResults.push({
          id: record.id,
          source: "health_record",
          title: record.title,
          date: record.date,
          provider: record.provider,
          facility: record.facility,
          summary: record.summary,
          status: "resulted",
          testCategory,
          components,
          hasAbnormal,
          hasCritical,
          abnormalCount,
          totalComponents: components.length,
        });
      }

      for (const order of labOrderRecords) {
        const results = order.results as any;
        const tests = order.tests as any[];
        let components: any[] = [];
        
        if (results?.components) {
          components = results.components.map(flagComponent);
        }
        
        const hasAbnormal = components.some((c: any) => c.isAbnormal);
        const hasCritical = components.some((c: any) => c.isCritical);
        const abnormalCount = components.filter((c: any) => c.isAbnormal).length;

        const testNames = tests?.map((t: any) => t.name).join(", ") || "Lab Order";
        const testCategory = tests?.[0]?.category || "general";
        
        consolidatedResults.push({
          id: order.id,
          source: "lab_order",
          title: testNames,
          date: order.resultedAt || order.submittedAt || order.createdAt,
          provider: order.providerId,
          facility: order.labProvider === "quest" ? "Quest Diagnostics" : order.labProvider === "labcorp" ? "LabCorp" : order.labProvider,
          summary: results?.status === "final" ? "Final results available" : null,
          status: order.status,
          orderNumber: order.orderNumber,
          accessionNumber: order.accessionNumber,
          priority: order.priority,
          testCategory,
          components,
          hasAbnormal,
          hasCritical,
          abnormalCount,
          totalComponents: components.length,
          labProvider: order.labProvider,
        });
      }

      const seen = new Set<string>();
      consolidatedResults = consolidatedResults.filter(r => {
        const key = `${r.title}-${new Date(r.date).toISOString().slice(0, 10)}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      });

      if (testType && String(testType) !== "all") {
        consolidatedResults = consolidatedResults.filter(r => r.testCategory === String(testType));
      }
      if (status && String(status) !== "all") {
        if (String(status) === "abnormal") {
          consolidatedResults = consolidatedResults.filter(r => r.hasAbnormal);
        } else {
          consolidatedResults = consolidatedResults.filter(r => r.status === String(status));
        }
      }
      if (startDate) {
        consolidatedResults = consolidatedResults.filter(r => new Date(r.date) >= new Date(String(startDate)));
      }
      if (endDate) {
        consolidatedResults = consolidatedResults.filter(r => new Date(r.date) <= new Date(String(endDate)));
      }

      const sortField = String(sortBy || "date");
      const order = String(sortOrder || "desc");
      consolidatedResults.sort((a, b) => {
        if (sortField === "date") {
          const diff = new Date(a.date).getTime() - new Date(b.date).getTime();
          return order === "asc" ? diff : -diff;
        }
        if (sortField === "testType") {
          const diff = (a.testCategory || "").localeCompare(b.testCategory || "");
          return order === "asc" ? diff : -diff;
        }
        if (sortField === "abnormal") {
          const diff = (b.abnormalCount || 0) - (a.abnormalCount || 0);
          return order === "asc" ? -diff : diff;
        }
        return 0;
      });

      const totalCount = consolidatedResults.length;
      const abnormalTotal = consolidatedResults.filter(r => r.hasAbnormal).length;
      const criticalTotal = consolidatedResults.filter(r => r.hasCritical).length;
      const pendingTotal = consolidatedResults.filter(r => r.status === "submitted" || r.status === "collected" || r.status === "pending").length;

      auditLog(req, "view_consolidated_lab_results", "labs", userId, { totalCount, abnormalTotal });

      res.json({
        results: consolidatedResults,
        summary: {
          total: totalCount,
          abnormal: abnormalTotal,
          critical: criticalTotal,
          pending: pendingTotal,
          normal: totalCount - abnormalTotal - pendingTotal,
        },
        categories: [...new Set(consolidatedResults.map(r => r.testCategory).filter(Boolean))],
      });
    } catch (error) {
      console.error("Consolidated lab results error:", error);
      res.status(500).json({ error: "Failed to load consolidated lab results" });
    }
  });

