  app.put("/api/intake/:intakeId/step", requireAuth, async (req: Request, res: Response) => {
    try {
      const { intakeId } = req.params as any;
      const { step, data } = req.body as any;

      const stepFieldMap: Record<number, string> = {
        0: "demographics",
        1: "medicalHistory",
        2: "allergies",
        3: "currentMedications",
        4: "socialHistory",
        5: "insuranceInfo",
      };

      const fieldName = stepFieldMap[step];
      if (fieldName === undefined) {
        return res.status(400).json({ error: "Invalid step number" });
      }

      const [existing] = await db
        .select()
        .from(comprehensiveIntakes)
        .where(eq(comprehensiveIntakes.id, intakeId));

      if (!existing) {
        return res.status(404).json({ error: "Intake not found" });
      }

      const completedSteps = Array.isArray(existing.completedSteps) ? [...(existing.completedSteps as number[])] : [];
      if (!completedSteps.includes(step)) {
        completedSteps.push(step);
      }

      const updateData: any = {
        [fieldName]: data,
        completedSteps,
        currentStep: Math.max(step + 1, (existing.currentStep || 0)),
        updatedAt: new Date(),
      };

      const [updated] = await db
        .update(comprehensiveIntakes)
        .set(updateData)
        .where(eq(comprehensiveIntakes.id, intakeId))
        .returning();

      auditLog(req, "update_intake_step", "intake", intakeId, { step, fieldName });
      res.json(updated);
    } catch (error) {
      console.error("Update intake step error:", error);
      res.status(500).json({ error: "Failed to update intake step" });
    }
  });


  app.post("/api/intake/:intakeId/complete", requireAuth, async (req: Request, res: Response) => {
    try {
      const { intakeId } = req.params as any;
      const userId = getUserId(req);

      const [intake] = await db
        .select()
        .from(comprehensiveIntakes)
        .where(eq(comprehensiveIntakes.id, intakeId));

      if (!intake) {
        return res.status(404).json({ error: "Intake not found" });
      }

      const demographics = intake.demographics as any;
      const medicalHistory = intake.medicalHistory as any;
      const allergies = intake.allergies as any;
      const medications = intake.currentMedications as any;

      const conditions: string[] = [];
      if (medicalHistory?.conditions && Array.isArray(medicalHistory.conditions)) {
        medicalHistory.conditions.forEach((c: any) => {
          conditions.push(typeof c === "string" ? c : c.name || c.condition);
        });
      }

      const symptoms: string[] = [];
      if (medicalHistory?.currentSymptoms && Array.isArray(medicalHistory.currentSymptoms)) {
        symptoms.push(...medicalHistory.currentSymptoms);
      }

      const medicationNames: string[] = [];
      if (medications?.medications && Array.isArray(medications.medications)) {
        medications.medications.forEach((m: any) => {
          medicationNames.push(typeof m === "string" ? m : m.name || m.medication);
        });
      }

      let cdsResults = null;
      try {
        cdsResults = await clinicalDecisionSupportService.analyzePatient({
          patientId: userId,
          symptoms,
          medications: medicationNames,
          conditions,
          context: "general",
        });
      } catch (cdsError) {
        console.error("CDS analysis during intake completion:", cdsError);
        cdsResults = { error: "CDS analysis unavailable", alerts: [] };
      }

      const [updated] = await db
        .update(comprehensiveIntakes)
        .set({
          status: "completed",
          completedAt: new Date(),
          cdsTriggered: true,
          cdsResults,
          updatedAt: new Date(),
        })
        .where(eq(comprehensiveIntakes.id, intakeId))
        .returning();

      if (demographics) {
        try {
          const profileData: any = {};
          if (demographics.firstName) profileData.firstName = demographics.firstName;
          if (demographics.lastName) profileData.lastName = demographics.lastName;
          if (demographics.dateOfBirth) profileData.dateOfBirth = new Date(demographics.dateOfBirth);
          if (demographics.gender) profileData.gender = demographics.gender;
          if (demographics.phone) profileData.phone = demographics.phone;
          if (demographics.email) profileData.email = demographics.email;
          if (demographics.addressLine1) profileData.addressLine1 = demographics.addressLine1;
          if (demographics.city) profileData.city = demographics.city;
          if (demographics.state) profileData.state = demographics.state;
          if (demographics.zipCode) profileData.zipCode = demographics.zipCode;
          if (demographics.race) profileData.race = demographics.race;
          if (demographics.ethnicity) profileData.ethnicity = demographics.ethnicity;
          if (demographics.preferredLanguage) profileData.preferredLanguage = demographics.preferredLanguage;
          if (demographics.maritalStatus) profileData.maritalStatus = demographics.maritalStatus;

          if (Object.keys(profileData).length > 0) {
            await storage.upsertPatientProfile(userId, profileData);
          }
        } catch (profileError) {
          console.error("Profile sync from intake:", profileError);
        }
      }

      if (allergies?.allergies && Array.isArray(allergies.allergies)) {
        for (const allergy of allergies.allergies) {
          try {
            await storage.createHealthRecord({
              userId,
              type: "allergy",
              title: typeof allergy === "string" ? allergy : allergy.allergen || allergy.name,
              summary: typeof allergy === "string" ? allergy : `${allergy.allergen || allergy.name} - ${allergy.reaction || "Unknown reaction"}`,
              date: new Date(),
              details: typeof allergy === "string" ? { allergen: allergy } : allergy,
              isManual: true,
            });
          } catch (e) {
            console.error("Error creating allergy record:", e);
          }
        }
      }

      if (medications?.medications && Array.isArray(medications.medications)) {
        for (const med of medications.medications) {
          try {
            await storage.createHealthRecord({
              userId,
              type: "medication",
              title: typeof med === "string" ? med : med.name || med.medication,
              summary: typeof med === "string" ? med : `${med.name || med.medication} ${med.dosage || ""} ${med.frequency || ""}`.trim(),
              date: new Date(),
              details: typeof med === "string" ? { name: med } : med,
              isManual: true,
            });
          } catch (e) {
            console.error("Error creating medication record:", e);
          }
        }
      }

      if (conditions.length > 0) {
        for (const condition of conditions) {
          try {
            await storage.createHealthRecord({
              userId,
              type: "condition",
              title: condition,
              summary: condition,
              date: new Date(),
              details: { condition, source: "patient_intake" },
              isManual: true,
            });
          } catch (e) {
            console.error("Error creating condition record:", e);
          }
        }
      }

      auditLog(req, "complete_intake", "intake", intakeId, {
        cdsTriggered: true,
        recordsCreated: {
          allergies: (allergies?.allergies || []).length,
          medications: (medications?.medications || []).length,
          conditions: conditions.length,
        },
      });

      res.json({ intake: updated, cdsResults });
    } catch (error) {
      console.error("Complete intake error:", error);
      res.status(500).json({ error: "Failed to complete intake" });
    }
  });


  app.post("/api/cds/lab-alerts", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { abnormalResults } = req.body as any;

      if (!abnormalResults || !Array.isArray(abnormalResults) || abnormalResults.length === 0) {
        return res.json({ alerts: [], message: "No abnormal results to analyze" });
      }

      const labSummary = abnormalResults.map((r: any) => {
        const abnormalComponents = (r.components || [])
          .filter((c: any) => c.isAbnormal)
          .map((c: any) => `${c.name}: ${c.value} ${c.units || ""} (ref: ${c.referenceRange?.text || "N/A"}, ${c.flag})`)
          .join("; ");
        return `${r.title} (${new Date(r.date).toLocaleDateString()}): ${abnormalComponents}`;
      }).join("\n");

      const userRecords = await db
        .select()
        .from(healthRecords)
        .where(and(eq(healthRecords.userId, userId), eq(healthRecords.type, "condition")))
        .orderBy(desc(healthRecords.date))
        .limit(20);

      const existingConditions = userRecords.map(r => r.title).join(", ") || "None documented";

      const medRecords = await db
        .select()
        .from(healthRecords)
        .where(and(eq(healthRecords.userId, userId), eq(healthRecords.type, "medication")))
        .orderBy(desc(healthRecords.date))
        .limit(20);

      const medications = medRecords.map(r => r.title).join(", ") || "None documented";

      let alerts: any[] = [];

      try {
        const response = await chatComplete({
          model: "deep",
          messages: [
            {
              role: "system",
              content: `You are a clinical decision support system. Analyze abnormal lab results and generate clinically relevant alerts.
For each significant finding, produce a structured alert with:
- category: one of "diagnostic_test", "diagnosis", "drug_interaction", "preventive", "safety"
- severity: one of "critical", "high", "moderate", "low", "info"
- title: concise alert title
- description: clinical explanation
- recommendations: array of actionable recommendations
- relatedTests: array of follow-up tests that should be considered

IMPORTANT: Include disclaimer that this is AI-generated decision support and not a substitute for clinical judgment.
Respond with valid JSON array of alerts.`
            },
            {
              role: "user",
              content: `Analyze these abnormal lab results for clinical significance:

ABNORMAL RESULTS:
${sanitizeHealthData(labSummary)}

EXISTING CONDITIONS: ${sanitizeHealthData(existingConditions)}
CURRENT MEDICATIONS: ${sanitizeHealthData(medications)}

Generate CDS alerts for clinically significant findings. Focus on:
1. Results requiring immediate attention (critical values)
2. Patterns suggesting underlying conditions
3. Drug-lab interactions
4. Recommended follow-up testing
5. Preventive care implications`
            }
          ],
          jsonMode: true,
          temperature: 0.3,
          dataCategories: ["conditions", "medications", "lab_results"],
          purpose: "clinical_decision_support",
          callerService: "routes",
          callerMethod: "labCdsAlerts",
        });

        const parsed = JSON.parse(response.content || '{"alerts":[]}');
        alerts = (parsed.alerts || []).map((a: any, idx: number) => ({
          id: `lab-cds-${Date.now()}-${idx}`,
          ...a,
          disclaimer: a.disclaimer || "AI-generated clinical decision support. Not a substitute for professional medical judgment.",
          source: "lab_results",
          generatedAt: new Date().toISOString(),
        }));
      } catch (aiError) {
        console.error("AI lab alert generation error:", aiError);
        alerts = abnormalResults.flatMap((r: any) => {
          return (r.components || [])
            .filter((c: any) => c.isAbnormal)
            .map((c: any, idx: number) => ({
              id: `lab-cds-rule-${Date.now()}-${idx}`,
              category: c.isCritical ? "safety" : "diagnostic_test",
              severity: c.isCritical ? "critical" : c.flag === "high" || c.flag === "low" ? "moderate" : "low",
              title: `Abnormal ${c.name}: ${c.value} ${c.units || ""}`,
              description: `${c.name} is ${c.flag} (${c.value} ${c.units || ""}). Reference range: ${c.referenceRange?.text || "N/A"}.`,
              recommendations: [
                c.isCritical ? "Immediate clinical review recommended" : "Consider repeating test to confirm results",
                "Review in context of patient's clinical history",
              ],
              relatedTests: [],
              disclaimer: "Rule-based alert. Consult with healthcare provider for clinical interpretation.",
              source: "lab_results",
              generatedAt: new Date().toISOString(),
            }));
        });
      }

      auditLog(req, "generate_lab_cds_alerts", "labs", userId, { alertCount: alerts.length, abnormalResultCount: abnormalResults.length });

      res.json({
        alerts,
        analyzedAt: new Date().toISOString(),
        abnormalResultCount: abnormalResults.length,
      });
    } catch (error) {
      console.error("CDS lab alerts error:", error);
      res.status(500).json({ error: "Failed to generate lab result alerts" });
    }
  });

