  app.get("/api/provider-discovery/session/:sessionId", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { sessionId } = req.params as any;
      const session = aiProviderDiscoveryService.getSession(sessionId);
      
      if (!session) {
        return res.status(404).json({ error: "Session not found" });
      }

      if (session.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      
      res.json({ session });
    } catch (error) {
      console.error("Get session error:", error);
      res.status(500).json({ error: "Failed to get session" });
    }
  });


  app.post("/api/provider-discovery/session/:sessionId/answer", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { sessionId } = req.params as any;
      const { questionId, answer } = req.body as any;

      const session = aiProviderDiscoveryService.getSession(sessionId);
      if (!session) {
        return res.status(404).json({ error: "Session not found" });
      }
      if (session.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }

      const nextQuestion = aiProviderDiscoveryService.addAnswer(sessionId, { questionId, answer });
      res.json({ nextQuestion, hasMoreQuestions: !!nextQuestion });
    } catch (error) {
      console.error("Add answer error:", error);
      res.status(500).json({ error: "Failed to add answer" });
    }
  });


