  // ==================== SYMPTOM TRACKING & ANALYSIS ====================


  app.post("/api/health-graph/symptoms", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const { name, severity, bodyLocation, duration, frequency, triggers, notes, onsetDate, snomedCode } = req.body as any;
      
      if (!name || severity === undefined || !onsetDate) {
        return res.status(400).json({ error: "Name, severity, and onsetDate are required" });
      }

      const node = healthGraphService.addSymptomNode(userId, {
        name,
        severity: Number(severity),
        bodyLocation,
        duration,
        frequency,
        triggers,
        notes,
        onsetDate: new Date(onsetDate),
        snomedCode
      });

      if (!node) {
        return res.status(404).json({ error: "Health graph not found. Please build the graph first." });
      }

      auditLog(req, "add_symptom", "symptom", userId, { symptomName: name, severity });
      res.json({ symptom: node });
    } catch (error) {
      console.error("Add symptom error:", error);
      res.status(500).json({ error: "Failed to add symptom" });
    }
  });


